Section AML.
Context {R : Type}.
Variable o : mem.
Variable Φ : R -> Prop.

Definition KOK (st : mstate) (k : mstate -> optr -> Malloc.M R) : Prop :=
  forall st2 mo r, LO st st2 -> leaf_of o (k st2 mo) r -> Φ r.
Definition BOK (bail : Malloc.M R) : Prop := forall r, leaf_of o bail r -> Φ r.

